import{_ as a,o,c as t,a2 as c}from"./chunks/framework.BS0bAV7E.js";const p=JSON.parse('{"title":"OTA 与 A/B 架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/ota-ab.md","filePath":"zh/arch/ota-ab.md"}'),d={name:"zh/arch/ota-ab.md"};function r(h,e,n,l,i,s){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="ota-与-a-b-架构" tabindex="-1">OTA 与 A/B 架构 <a class="header-anchor" href="#ota-与-a-b-架构" aria-label="Permalink to &quot;OTA 与 A/B 架构&quot;">​</a></h1><h2 id="槽位与标志" tabindex="-1">槽位与标志 <a class="header-anchor" href="#槽位与标志" aria-label="Permalink to &quot;槽位与标志&quot;">​</a></h2><p><code>kernel/ota/ota_ab.{c,h}</code>：两个槽位 + 一个启动标志 + 每槽位状态（成功 / 启动中 / 失败）。GRUB 的菜单脚本读取该标志；<code>update</code> 在分阶段安装后写入它；<code>rollback</code> 将其翻转回去。</p><h2 id="更新链" tabindex="-1">更新链 <a class="header-anchor" href="#更新链" aria-label="Permalink to &quot;更新链&quot;">​</a></h2><p><code>kernel/ota/ota_update.{c,h}</code>：检查（获取并解析清单）、下载（通过 HTTP/HTTPS 到文件）、验证（SHA256 + 签名）、安装（到非活动槽位）、设置启动（标志）、回滚，以及状态查询。L1 接口面 1:1 地镜像了这些操作（<code>l1_ext_check_update</code>、<code>l1_ext_update_download</code> 等）。</p><h2 id="清单" tabindex="-1">清单 <a class="header-anchor" href="#清单" aria-label="Permalink to &quot;清单&quot;">​</a></h2><p>发布站点上的 <code>update.json</code>：版本、构建、时间、变更、软件包 URL、软件包 SHA256、软件包大小。<code>checkupdate</code> 从 <code>/etc/opencube.conf</code> 读取该 URL 并精确解析此内容。</p><h2 id="软件包" tabindex="-1">软件包 <a class="header-anchor" href="#软件包" aria-label="Permalink to &quot;软件包&quot;">​</a></h2><p><code>opencube-&lt;version&gt;-update.tar.gz</code>：新的内核 ELF + 清单。在构建日内是确定性的（清单嵌入了 UTC 日期）；ELF 本身是完全可复现的。</p><h2 id="客户端内测试" tabindex="-1">客户端内测试 <a class="header-anchor" href="#客户端内测试" aria-label="Permalink to &quot;客户端内测试&quot;">​</a></h2><p><code>ab_partition_test</code>、<code>update_*_test</code>（整个链路，打包为命令）、<code>checkupdate_test</code>（URL/JSON 单元 + 实时探测），以及执行检查→下载→验证→安装→重启真实流程的发布门禁 E2E。</p>',11)])])}const u=a(d,[["render",r]]);export{p as __pageData,u as default};
